using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.Rendering;
namespace ParkingLotEnvironment.CloudPilot {public static class ReviewDelivery {
 public static void Run(){try{string w="Assets/ParkingLotEnvironment/CloudPilot/WholeMapFinish20261105";var args=Environment.GetCommandLineArgs();string output=args[Array.IndexOf(args,"-collabOutput")+1];EditorSceneManager.OpenScene(w+"/WholeMapReview.unity");var root=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name=="ParkingLot_CornerPilot_Root");var cam=root.GetComponentInChildren<Camera>();cam.enabled=true;int probeIndex=0;foreach(var probe in root.GetComponentsInChildren<ReflectionProbe>(true)){if(probe.name.Contains("LeftVehicles"))probe.transform.position=new Vector3(-1.7f,2.5f,-9);if(probe.name.Contains("RightVehicles"))probe.transform.position=new Vector3(3.0f,2.5f,-1);probe.boxProjection=true;probe.mode=ReflectionProbeMode.Baked;probe.customBakedTexture=null;string path=w+"/AisleReflection"+(probeIndex++)+".exr";if(!Lightmapping.BakeReflectionProbe(probe,path))throw new Exception("Probe failed");AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);probe.mode=ReflectionProbeMode.Custom;probe.customBakedTexture=AssetDatabase.LoadAssetAtPath<Texture>(path);EditorUtility.SetDirty(probe);}AssetDatabase.SaveAssets();ContextBuilder.Validate(root,output);int slots=0;foreach(var r in root.GetComponentsInChildren<Renderer>())foreach(var m in r.sharedMaterials){if(!m||!m.shader||!m.shader.isSupported||ShaderUtil.ShaderHasError(m.shader))throw new Exception("Invalid material on "+r.name);slots++;}EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());var p=new Vector3(.7f,1.65f,-17.5f);cam.transform.SetPositionAndRotation(p,Quaternion.LookRotation(new Vector3(.7f,1.65f,-6.7f)-p));var rt=new RenderTexture(2560,1440,24,RenderTextureFormat.ARGBHalf);rt.Create();cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(2560,1440,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,2560,1440),0,0);tex.Apply();File.WriteAllBytes(output+"/first-person.png",tex.EncodeToPNG());cam.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);Extra(cam,output,"overview.png",new Vector3(.7f,2.8f,-17.5f),new Vector3(.7f,1.2f,-6.7f));Extra(cam,output,"vehicles.png",new Vector3(-.1f,1.55f,-15.3f),new Vector3(-5.1f,1,-13.5f));Extra(cam,output,"porter.png",new Vector3(-.3f,1.75f,-7),new Vector3(-5,1,-4.5f));Extra(cam,output,"aerial.png",new Vector3(23,29,-35),new Vector3(0,1,-4));Extra(cam,output,"entrance.png",new Vector3(.7f,3.6f,-33),new Vector3(.7f,2.1f,-20));File.WriteAllText(output+"/delivery-validation.txt","Reopened baked scene; enabled scene camera; checked "+slots+" material slots; all shaders supported and without compile errors; parking layout validation passed. First-person 2560x1440 rendered. Capture camera movement not saved.");EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 static void Extra(Camera cam,string output,string name,Vector3 p,Vector3 target){cam.transform.SetPositionAndRotation(p,Quaternion.LookRotation(target-p));var rt=new RenderTexture(2560,1440,24,RenderTextureFormat.ARGBHalf);rt.Create();cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(2560,1440,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,2560,1440),0,0);tex.Apply();File.WriteAllBytes(output+"/"+name,tex.EncodeToPNG());cam.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}
}}
